export function HeroSection({
  headline = "{{headline}}",
  subhead = "{{subhead}}",
  ctaLabel = "{{ctaLabel}}",
  align = "{{align}}",
  bg = "{{bg}}",
}) {
  return (
    <section style={{ padding: "64px 32px", color: "#FAF7F2", background: bg, textAlign: align, fontFamily: "system-ui, sans-serif", boxSizing: "border-box" }}>
      <div style={{ maxWidth: 560, margin: align === "center" ? "0 auto" : "0" }}>
        <h1 style={{ margin: "0 0 14px", fontSize: 36, fontWeight: 700, letterSpacing: "-.02em" }}>{headline}</h1>
        <p style={{ margin: "0 0 26px", fontSize: 16, opacity: .82 }}>{subhead}</p>
        <button type="button" style={{ background: "#FAF7F2", color: "#241430", border: "none", padding: "13px 26px", borderRadius: 10, fontSize: 15, fontWeight: 600, cursor: "pointer" }}>{ctaLabel}</button>
      </div>
    </section>
  );
}
